type Customer={id:number;name:string;mobile:string;place:string;balance:number};
type BillItem={productId:number;name:string;qty:number;price:number;expense:number;total:number};
type Bill={id:number;billNo:string;date:string;customer:Customer;items:BillItem[];subtotal:number;paid:number;balance:number;payment:'Cash'|'GPay / UPI'|'Credit';expense:number;profit:number;status:'Completed'};
type StockLog={id:number;productId:number;productName:string;qty:number;expense:number;date:string;type:'Purchase'|'Adjustment'};

